/**
 * Static structure of the HMI Template Suite V6.0 for WinCC Unified V20.
 * Derived from the Siemens V6.0 manual (Entry ID 91174767, 10/2025).
 *
 * Pac-Forge uses this as the source of truth for:
 * - Which predefined screens exist in the Template Suite after the wizard runs
 * - Which screen windows the Template Suite wires up and what they contain
 * - Standard layout zones and their purpose (title bar, status bar, MainWindow, nav bars)
 * - The 4-level navigation model
 * - Tag conventions the Template Suite expects on the PLC side
 *
 * These values are NEVER generated by Pac-Forge — they come from the Template Suite
 * library imported via the HMI Template Suite Wizard. Pac-Forge references them by name.
 */

import type { HmiPanelConfig } from "@/types/hmi-panel";

// ---------------------------------------------------------------------------
// Layout zones — named regions in the 1001_ScreenLayout master screen
// ---------------------------------------------------------------------------

export const HMI_LAYOUT_ZONES = {
  TITLE_BAR: "titleBar",
  STATUS_BAR: "statusBar",
  MAIN_WINDOW: "mainWindow",
  MAIN_NAVIGATION: "mainNavigation",
  SUB_NAVIGATION: "subNavigation",
  THIRD_LEVEL_NAV: "thirdLevelNav",
  TAB_NAV: "tabNav",
} as const;

export type HmiLayoutZone =
  (typeof HMI_LAYOUT_ZONES)[keyof typeof HMI_LAYOUT_ZONES];

export const HMI_LAYOUT_ZONE_LABELS: Record<HmiLayoutZone, string> = {
  titleBar: "Title Bar",
  statusBar: "Status Bar",
  mainWindow: "Main Window (application area)",
  mainNavigation: "Main Navigation (1st level)",
  subNavigation: "Sub Navigation (2nd level)",
  thirdLevelNav: "Third-Level Navigation",
  tabNav: "Tab Navigation (4th level)",
};

// ---------------------------------------------------------------------------
// Predefined Template Suite screens
// These ALREADY exist in the target TIA project after the wizard runs.
// Pac-Forge references them by name, never generates them.
// ---------------------------------------------------------------------------

export const HMI_TEMPLATE_SCREENS = {
  /** Start screen and layout master — contains title bar, status bar, swContent, swMainNavigation. */
  SCREEN_LAYOUT: "1001_ScreenLayout",
  /** First-level navigation screen (Application / Messages / Settings). Loaded into swMainNavigation. */
  MAIN_NAVIGATION: "1002_MainNavigation",
  /** Second-level nav layout wrapping swSubNavContent + nav bar. Loaded into swContent. */
  SCREEN_LAYOUT_SUB_NAV: "1101_ScreenLayout_SubNav",
  /** Fourth-level tab navigation layout. Loaded into swContent when tab-nav is used. */
  SCREEN_LAYOUT_TAB_NAV: "1300_ScreenLayout_TabNav",
  /** Default application area — replaced with Pac-Forge-generated content. */
  APPLICATION: "0001_Application",
  /** Global messages / alarms page. */
  MESSAGES: "0002_Messages",
  /** Device settings page (brightness, etc.). */
  SETTINGS: "0003_Settings",
} as const;

export type HmiTemplateScreen =
  (typeof HMI_TEMPLATE_SCREENS)[keyof typeof HMI_TEMPLATE_SCREENS];

