// ---------------------------------------------------------------------------
// Screen windows — dynamic content containers defined in Template Suite
// ---------------------------------------------------------------------------

export const HMI_SCREEN_WINDOWS = {
  /** Main content container in 1001_ScreenLayout (usually holds 1101_ScreenLayout_SubNav). */
  CONTENT: "swContent",
  /** Application screen container inside 1101_ScreenLayout_SubNav. */
  SUB_NAV_CONTENT: "swSubNavContent",
  /** Right-side overlay navigation in 1001_ScreenLayout (hamburger menu target). */
  MAIN_NAVIGATION: "swMainNavigation",
} as const;

export type HmiScreenWindow =
  (typeof HMI_SCREEN_WINDOWS)[keyof typeof HMI_SCREEN_WINDOWS];

// ---------------------------------------------------------------------------
// Navigation levels
// ---------------------------------------------------------------------------

export const HMI_NAV_LEVELS = {
  /** Hamburger menu overlay, top-right of title bar, loads 1002_MainNavigation. */
  MAIN: "main",
  /** Bottom bar inside 1101_ScreenLayout_SubNav. */
  SUB: "sub",
  /** Left sidebar, optional. */
  THIRD: "third",
  /** Top tabs, optional, uses 1300_ScreenLayout_TabNav. */
  TAB: "tab",
} as const;

export type HmiNavLevel = (typeof HMI_NAV_LEVELS)[keyof typeof HMI_NAV_LEVELS];

