// ---------------------------------------------------------------------------
// Layout zone rectangles — proportional hints
// ---------------------------------------------------------------------------

export interface LayoutZoneRect {
  top: number;
  left: number;
  width: number;
  height: number;
}

/**
 * Percent-based proportions for layout zones when all nav levels are visible.
 * Derived from V6.0 manual Figure 4-9 and the preconfigured 1001_ScreenLayout panels.
 * Values are percentages of the panel's native resolution.
 */
export const HMI_TEMPLATE_LAYOUT_PERCENT: Record<HmiLayoutZone, LayoutZoneRect> = {
  titleBar:       { top: 0,   left: 0,  width: 100, height: 6 },
  statusBar:      { top: 6,   left: 0,  width: 100, height: 4 },
  mainWindow:     { top: 10,  left: 0,  width: 100, height: 84 },
  mainNavigation: { top: 6,   left: 80, width: 20,  height: 88 },
  subNavigation:  { top: 94,  left: 0,  width: 100, height: 6 },
  thirdLevelNav:  { top: 10,  left: 0,  width: 15,  height: 84 },
  tabNav:         { top: 10,  left: 0,  width: 100, height: 4 },
};

/**
 * Compute the absolute pixel rect of a layout zone for a given panel.
 * Handles the 8-pixel grid snap documented in Section 3.3.
 */
export function getZoneRect(
  zone: HmiLayoutZone,
  panel: HmiPanelConfig,
): { x: number; y: number; width: number; height: number } {
  const pct = HMI_TEMPLATE_LAYOUT_PERCENT[zone];
  const grid = HMI_TEMPLATE_DESIGN.GRID_PX;

  const rawX = (pct.left / 100) * panel.screenWidth;
  const rawY = (pct.top / 100) * panel.screenHeight;
  const rawW = (pct.width / 100) * panel.screenWidth;
  const rawH = (pct.height / 100) * panel.screenHeight;

  return {
    x: Math.round(rawX / grid) * grid,
    y: Math.round(rawY / grid) * grid,
    width: Math.round(rawW / grid) * grid,
    height: Math.round(rawH / grid) * grid,
  };
}

/**
 * Compute the MainWindow rect after subtracting visible navigation levels.
 * Pac-Forge generated content should fit inside this rect.
 */
export function getContentRect(
  panel: HmiPanelConfig,
  visibleNavLevels: Set<HmiNavLevel>,
): { x: number; y: number; width: number; height: number } {
  const mainWindow = getZoneRect(HMI_LAYOUT_ZONES.MAIN_WINDOW, panel);
  let { x, y, width, height } = mainWindow;

  if (visibleNavLevels.has(HMI_NAV_LEVELS.SUB)) {
    const sub = getZoneRect(HMI_LAYOUT_ZONES.SUB_NAVIGATION, panel);
    height -= sub.height;
  }
  if (visibleNavLevels.has(HMI_NAV_LEVELS.THIRD)) {
    const third = getZoneRect(HMI_LAYOUT_ZONES.THIRD_LEVEL_NAV, panel);
    x += third.width;
    width -= third.width;
  }
  if (visibleNavLevels.has(HMI_NAV_LEVELS.TAB)) {
    const tab = getZoneRect(HMI_LAYOUT_ZONES.TAB_NAV, panel);
    y += tab.height;
    height -= tab.height;
  }

  return { x, y, width, height };
}

// ---------------------------------------------------------------------------
// Folder paths inside the Template Suite library
// Used when the wizard copies master copies or when the bridge enumerates items.
// ---------------------------------------------------------------------------

export const HMI_TEMPLATE_LIBRARY_PATHS = {
  /** Root library name (Light variant). */
  LIGHT_ROOT: "HMI Template Suite Light (WinCC Unified)_V20",
  /** Root library name (Dark variant). */
  DARK_ROOT: "HMI Template Suite Dark (WinCC Unified)_V20",
  /** Types folder holds the 3 Template Suite faceplate types. */
  TYPES: "Types",
  /** Master copies hold the preconfigured panels, layouts, and templates. */
  MASTER_COPIES: "Master copies",
  /** Top-level folder inside Master copies. */
  HMI_TEMPLATE_SUITE: "HMI Template Suite",
  /** Panel family container (WinCC Unified vs View of Things). */
  WINCC_UNIFIED: "WinCC Unified",
  /** Sub-folder per resolution. */
  RESOLUTION_FOLDERS: {
    R800x480: "02 - 800 x 480",
    R1280x800: "03 - 1280 x 800",
    R1366x768: "04 - 1366 x 768",
    R1920x1080: "05 - 1920 x 1080",
  },
  /** Sub-folder per content type inside each resolution folder. */
  CONTENT_FOLDERS: {
    DEVICE: "00 - Device",
    SCREEN_LAYOUT: "01 - Screen layout",
    SCREENS: "02 - Screens",
    POPUP_SCREENS: "03 - Popup screens",
    OTHER_TEMPLATES: "04 - Other Templates",
  },
} as const;

/**
 * Resolve the Template Suite library root path for a given theme.
 */
export function getLibraryRoot(theme: "SiemensLight" | "SiemensDark" | "DeepBlue"): string {
  // DeepBlue is a palette within the Dark library (per V6.0 manual Section 3.2.5)
  if (theme === "SiemensDark" || theme === "DeepBlue") {
    return HMI_TEMPLATE_LIBRARY_PATHS.DARK_ROOT;
  }
  return HMI_TEMPLATE_LIBRARY_PATHS.LIGHT_ROOT;
}
